CREATE TABLE `delivery_records` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `delivery_month` varchar(255) DEFAULT NULL,
  `delivery_day` int(2) NOT NULL COMMENT 'Day of delivery (1-31)',
  `delivery_year` int(4) DEFAULT NULL COMMENT 'Year of delivery (e.g., 2025, 2026)',
  `record_date` date DEFAULT NULL COMMENT 'Original Excel Date column',
  `delivery_date` date DEFAULT NULL COMMENT 'Date Delivered column',
  `item_code` varchar(255) DEFAULT NULL,
  `item_name` varchar(255) DEFAULT NULL,
  `company_name` varchar(255) DEFAULT NULL,
  `sold_to` varchar(255) DEFAULT NULL,
  `quantity` int(11) NOT NULL DEFAULT 0 COMMENT 'Number of units delivered',
  `status` varchar(255) DEFAULT NULL,
  `highlight_color` varchar(255) DEFAULT NULL,
  `cell_styles` longtext DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp() COMMENT 'Record creation timestamp',
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Record last update timestamp',
  `dataset_name` varchar(255) DEFAULT NULL,
  `record_type` varchar(20) DEFAULT 'inventory',
  `order_customer` varchar(255) DEFAULT NULL,
  `order_date` date DEFAULT NULL,
  `unit_price` decimal(12,2) DEFAULT 0.00,
  `total_amount` decimal(12,2) DEFAULT 0.00,
  `po_number` varchar(255) DEFAULT NULL,
  `peso_cost` decimal(15,2) DEFAULT 0.00,
  `foreign_cost` decimal(15,2) DEFAULT 0.00,
  `po_status` varchar(255) DEFAULT NULL,
  `invoice_no` varchar(100) DEFAULT NULL,
  `serial_no` varchar(150) DEFAULT NULL,
  `groupings` varchar(255) DEFAULT NULL,
  `transferred_to` varchar(255) DEFAULT NULL,
  `box_code` varchar(50) DEFAULT NULL,
  `model_no` varchar(100) DEFAULT NULL,
  `uom` varchar(50) DEFAULT NULL,
  `sold_to_month` varchar(20) DEFAULT NULL,
  `sold_to_day` int(11) DEFAULT NULL,
  `box` varchar(255) DEFAULT NULL,
  `items` varchar(255) DEFAULT NULL,
  `inventory` varchar(255) DEFAULT NULL,
  `owner_user_id` int(11) DEFAULT NULL,
  `inventory_status` varchar(50) DEFAULT NULL COMMENT 'Inventory classification: INVENTORY, Stock in Manila, or NULL for sales',
  `unit_type` varchar(10) DEFAULT NULL COMMENT 'Unit Type (1a, 1b, 2a, 2b, 3a, 4a)',
  `warranty_items` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_delivery_month` (`delivery_month`),
  KEY `idx_delivery_day` (`delivery_day`),
  KEY `idx_delivery_year` (`delivery_year`),
  KEY `idx_item_code` (`item_code`),
  KEY `idx_company_name` (`company_name`),
  KEY `idx_status` (`status`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_owner_user_id` (`owner_user_id`),
  KEY `idx_po_status` (`po_status`),
  KEY `idx_record_type` (`record_type`),
  KEY `idx_dataset_year` (`dataset_name`,`delivery_year`),
  KEY `idx_dataset_created` (`dataset_name`,`created_at`),
  KEY `idx_unit_type` (`unit_type`)
) ENGINE=InnoDB AUTO_INCREMENT=208120 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores delivery records for BW Gas Detector products';

